import java.io.File

/**
 * Rewrites the accessor files generated by the Compose resources plugin so that reading one
 * resource does not load one lambda class per resource of the whole file.
 *
 * The generator emits `val Res.string.x by lazy { StringResource(...) }`; with class-based lambdas the first
 * access initialises every property of the file and loads about one class per resource. The rewrite keeps the
 * same lazy, thread-safe, identity-stable properties but builds each value in a shared `when` function.
 */
object ResourceAccessorRewriter {
    private const val CHUNK_SIZE = 40

    private val property = Regex(
        """(@delegate:ResourceContentHash\(-?[\d_]+\)\n)internal val (Res\.\w+\.(\w+)): (\w+) by lazy \{\n\s*(.*?)\n\s*\}\n""",
        RegexOption.DOT_MATCHES_ALL,
    )

    private data class Accessor(val annotation: String, val receiver: String, val name: String, val type: String, val body: String)

    fun rewrite(directory: File) = directory.walkTopDown()
        .filter { it.isFile && it.extension == "kt" }
        .forEach { file -> file.writeText(rewrite(file.readText(), file.nameWithoutExtension.substringBefore('.'))) }

    fun rewrite(source: String, tablePrefix: String): String {
        val accessors = property.findAll(source).map(::toAccessor).toList()
        if (accessors.isEmpty()) return source
        val header = source.substring(0, property.find(source)!!.range.first)
        val chunks = accessors.chunked(CHUNK_SIZE)
        return buildString {
            append(header)
            accessors.forEachIndexed { index, accessor -> append(propertyOf(accessor, "${tablePrefix}Table${index / CHUNK_SIZE}")) }
            chunks.forEachIndexed { index, chunk -> append(tableOf(chunk, "${tablePrefix}Table$index")) }
        }
    }

    private fun toAccessor(match: MatchResult) = match.destructured.let { (annotation, receiver, name, type, body) ->
        Accessor(annotation, receiver, name, type, body.trim())
    }

    private fun propertyOf(accessor: Accessor, table: String) =
        "${accessor.annotation}internal val ${accessor.receiver}: ${accessor.type} by lazy($table(\"${accessor.name}\"))\n\n"

    private fun tableOf(chunk: List<Accessor>, table: String): String {
        val type = chunk.first().type
        val cases = chunk.joinToString("\n") { "        \"${it.name}\" -> ${it.body}" }
        return "private class $table(private val key: String) : () -> $type {\n" +
            "    override fun invoke(): $type = when (key) {\n$cases\n        else -> error(key)\n    }\n}\n\n"
    }
}
